namespace GameLauncherGUI;

internal sealed class StrategyProfilesForm : StudioDialog
{
    private static string Hash(IEnumerable<string> descriptors)=>Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(string.Join("\n",descriptors))));
    private static void Mark(StrategyModsManager manager,string name,string[] descriptors)=>LocalJson.Write(ModInstaller.SafePath(manager.UserRoot,".playspace-mods/active-named-strategy.json"),new Dictionary<string,string>{{"name",name},{"hash",Hash(descriptors)}});
    internal static string ActiveName(StrategyModsManager manager)
    {
        try{var current=LocalJson.Read(ModInstaller.SafePath(manager.UserRoot,".playspace-mods/strategy-profile.json"),()=>new Dictionary<string,object>());var active=LocalJson.Read(ModInstaller.SafePath(manager.UserRoot,".playspace-mods/active-named-strategy.json"),()=>new Dictionary<string,string>());string[] descriptors=current.TryGetValue("Enabled",out var enabled)&&enabled is Newtonsoft.Json.Linq.JArray entries?entries.Values<string>().Where(s=>s!=null).Select(s=>s!).ToArray():Array.Empty<string>();return descriptors.Length==0?"Без модов PlaySpace / Paradox":active.GetValueOrDefault("hash")==Hash(descriptors)?active.GetValueOrDefault("name")??"Текущий набор Paradox":"Текущий набор Paradox изменён";}catch(Exception ex)when(ex is IOException or InvalidDataException or UnauthorizedAccessException){return "Набор Paradox не определён";}
    }
    private sealed record Profile(string Name,string[] Descriptors){public override string ToString()=>Name+" · "+Descriptors.Length+" модов";}
    internal StrategyProfilesForm(GameInfo game,StrategyModsManager manager)
    {
        string file=ModInstaller.SafePath(manager.UserRoot,".playspace-mods/named-strategy-profiles.json");var profiles=LocalJson.Read(file,()=>new List<Profile>());bool busy=false;
        Text="PLAYSPACE / Наборы Paradox · "+game.Name;Size=new Size(820,570);MinimumSize=new Size(740,500);var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=5,Padding=new Padding(28)};foreach(float h in new[]{44F,44F})layout.RowStyles.Add(new RowStyle(SizeType.Absolute,h));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,50));ContentHost.Controls.Add(layout);
        var picker=new ModernSelect{Dock=DockStyle.Fill};picker.SetPlaceholder("Сохранённых наборов пока нет");var name=new TextBox{Dock=DockStyle.Fill,PlaceholderText="Название набора"};var details=new FormattedDescription{Dock=DockStyle.Fill,Text="Сохраняются активные моды и порядок загрузки PlaySpace. Workshop-файлы должны оставаться установленными. Профили официального Paradox Launcher не переименовываются."};var status=new Label{Dock=DockStyle.Fill};layout.Controls.Add(picker,0,0);layout.Controls.Add(name,0,1);layout.Controls.Add(details,0,2);layout.Controls.Add(status,0,4);
        var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=false};var save=new ModernButton("Сохранить текущий набор",VisualTheme.Accent){Width=245,Height=40};var apply=new ModernButton("Активировать",Color.FromArgb(35,40,63)){Width=180,Height=40};var empty=new ModernButton("Без модов",Color.FromArgb(35,40,63)){Width=180,Height=40};buttons.Controls.Add(save);buttons.Controls.Add(apply);buttons.Controls.Add(empty);layout.Controls.Add(buttons,0,3);
        void Refresh(){picker.SelectedIndex=-1;picker.Items.Clear();foreach(var profile in profiles)picker.Items.Add(profile);if(picker.Items.Count>0)picker.SelectedIndex=0;}
        async Task Run(Action work,string history){if(busy)return;busy=true;buttons.Enabled=false;try{await Task.Run(work);Workspace.Current.History.Add(game,"Моды",history);status.Text="Набор сохранён или активирован. Он применяется при запуске через PlaySpace.";Refresh();}catch(Exception ex)when(ex is IOException or InvalidDataException or ArgumentException or UnauthorizedAccessException){status.Text=ex.Message;}finally{busy=false;buttons.Enabled=true;}}
        save.Click+=async(s,e)=>{string title=name.Text;await Run(()=>{title=LibraryCollections.Name(title);if(profiles.Count>=20||profiles.Any(p=>p.Name.Equals(title,StringComparison.OrdinalIgnoreCase)))throw new IOException("Имя занято или достигнут лимит 20 наборов.");var list=manager.List();var descriptors=list.Where(m=>m.Enabled&&m.Descriptor!=null).Select(m=>m.Descriptor!).ToArray();var next=profiles.Append(new Profile(title,descriptors)).ToList();LocalJson.Write(file,next);profiles=next;Mark(manager,title,descriptors);},"Сохранён набор Paradox");};apply.Click+=async(s,e)=>{if(picker.SelectedItem is Profile p)await Run(()=>{manager.ApplyNamedProfile(p.Descriptors);Mark(manager,p.Name,p.Descriptors);},"Активирован набор Paradox: "+p.Name);};empty.Click+=async(s,e)=>await Run(()=>{manager.ApplyNamedProfile(Array.Empty<string>());Mark(manager,"Без модов",Array.Empty<string>());},"Отключены моды в профиле PlaySpace Paradox");picker.SelectedIndexChanged+=(s,e)=>{if(picker.SelectedItem is Profile p)details.Text=p.Name+"\n\n"+string.Join("\n",p.Descriptors);};Shown+=(s,e)=>Refresh();FormClosing+=(s,e)=>{if(busy)e.Cancel=true;};
    }
}
